import os
from sqlalchemy import create_engine, text
url=(os.environ.get("DATABASE_URL") or os.environ.get("PVESPS_DATABASE_URL"))
url=url.replace("@localhost:","@host.docker.internal:").replace("@127.0.0.1:","@host.docker.internal:")
engine=create_engine(url,pool_pre_ping=True)
ddl=text("""CREATE TABLE IF NOT EXISTS mart.fact_weather_forecast_snapshot (snapshot_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, snapshot_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, source_run_id BIGINT NOT NULL, location_sk INTEGER NOT NULL, forecast_issue_time TIMESTAMPTZ NOT NULL, forecast_start_time TIMESTAMPTZ NOT NULL, forecast_end_time TIMESTAMPTZ NOT NULL, pop_type VARCHAR(30), pop_value NUMERIC(8,2), dispatch_recommended BOOLEAN, loaded_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_weather_forecast_snapshot UNIQUE (source_run_id,location_sk,forecast_issue_time,forecast_start_time,forecast_end_time))""")
snapshot_sql=text("""INSERT INTO mart.fact_weather_forecast_snapshot (source_run_id,location_sk,forecast_issue_time,forecast_start_time,forecast_end_time,pop_type,pop_value,dispatch_recommended,temperature_c,relative_humidity_pct,wind_speed_ms,weather_description,uv_index,rain_risk_flag,cloudy_risk_flag) SELECT run_id,location_sk,forecast_issue_time,forecast_start_time,forecast_end_time,pop_type,pop_value,dispatch_recommended,temperature_c,relative_humidity_pct,wind_speed_ms,weather_description,uv_index,rain_risk_flag,cloudy_risk_flag FROM mart.fact_weather_forecast ON CONFLICT (source_run_id,location_sk,forecast_issue_time,forecast_start_time,forecast_end_time) DO NOTHING""")
latest_sql=text("""INSERT INTO mart.fact_weather_forecast_latest (location_sk,forecast_issue_time,forecast_start_time,forecast_end_time,pop_type,pop_value,dispatch_recommended,temperature_c,relative_humidity_pct,wind_speed_ms,weather_description,uv_index,rain_risk_flag,cloudy_risk_flag) SELECT location_sk,forecast_issue_time,forecast_start_time,forecast_end_time,pop_type,pop_value,dispatch_recommended,temperature_c,relative_humidity_pct,wind_speed_ms,weather_description,uv_index,rain_risk_flag,cloudy_risk_flag FROM mart.fact_weather_forecast ON CONFLICT (location_sk,forecast_start_time,forecast_end_time,pop_type) DO UPDATE SET forecast_issue_time=EXCLUDED.forecast_issue_time,pop_value=EXCLUDED.pop_value,dispatch_recommended=EXCLUDED.dispatch_recommended,temperature_c=EXCLUDED.temperature_c,relative_humidity_pct=EXCLUDED.relative_humidity_pct,wind_speed_ms=EXCLUDED.wind_speed_ms,weather_description=EXCLUDED.weather_description,uv_index=EXCLUDED.uv_index,rain_risk_flag=EXCLUDED.rain_risk_flag,cloudy_risk_flag=EXCLUDED.cloudy_risk_flag,loaded_at=CURRENT_TIMESTAMP""")
with engine.begin() as conn:
    conn.execute(ddl)
    snapshot_result=conn.execute(snapshot_sql)
    latest_result=conn.execute(latest_sql)
print(f"[WEATHER_SNAPSHOT] appended rows={snapshot_result.rowcount}; latest upsert rows={latest_result.rowcount}")

